KG42.register("rules-188e89da0f2f50726edceec5",{"id":"11-p2p_mechanisms_evaluation::v141-c-R014","paper":"11-p2p_mechanisms_evaluation","record":{"rule_id":"v141-c-R014","mechanism_id":"v141-a-M02","name":"Local clearing price","process_stage":"pricing","market_meaning":"Submitted generation quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. Submitted demand quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. The coordinator calculates internal prices using the MMR pricing model. Scope: MMR pricing within one energy sharing region. The internal buying and selling prices are equal to the arithmetic mean of the retailer's export and retail prices. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation equals total demand. The internal selling price remains the arithmetic mean of export and retail prices; the internal buying price is adjusted to cover the regional deficit imported at the retailer's retail price. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation is less than total demand. The internal buying price remains the arithmetic mean of export and retail prices; the internal selling price is adjusted to incorporate surplus-export income for distribution among participants providing electricity through generation or EV discharging. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation exceeds total demand.","independence_rationale":"Relations governed by the approved function pricing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","coordination.local_operator","pricing.local"],"E":[{"edge_id":"v141-c-R014-E001","source":"bidding.demand","target":"pricing.local","type":"links","constraint_ids":["v141-c-R014-C002"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},{"edge_id":"v141-c-R014-E002","source":"bidding.supply","target":"pricing.local","type":"links","constraint_ids":["v141-c-R014-C001"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},{"edge_id":"v141-c-R014-E003","source":"coordination.local_operator","target":"pricing.local","type":"links","constraint_ids":["v141-c-R014-C003"],"evidence_ids":["v141-b-g07-ev-07"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"MMR internal prices at a given time step within one energy sharing region. | MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step. | MMR pricing within one energy sharing region.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},"x":[{"variable_id":"p_buy_t","symbol":"p_t^{buy}","meaning":"Internal buying price issued by the coordinator for time step t under the MMR pricing model; endogenous output of the pricing.local node, fully determined by A25-A27 from the submitted generation/demand totals and the retailer's prices (not a free choice and not an optimization decision).","kind":"operational","domain":"Real-valued price at each time step t ∈ T; the source (A25)-(A27) states no explicit numeric bound or sign restriction.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-07"]},{"variable_id":"p_sell_t","symbol":"p_t^{sell}","meaning":"Internal selling price issued by the coordinator for time step t under the MMR pricing model; endogenous output of the pricing.local node, fully determined by A25-A27 from the submitted generation/demand totals and the retailer's prices (not a free choice and not an optimization decision).","kind":"operational","domain":"Real-valued price at each time step t ∈ T; the source (A25)-(A27) states no explicit numeric bound or sign restriction.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-07"]}],"theta":[{"parameter_id":"r_retail_t","symbol":"r_t^{retail}","meaning":"Retail price at which the coordinator buys electricity from the retailer for time step t; a pre-announced, non-dynamic exogenous input to the MMR pricing formula (retailer counterparty is outside this rule's graph).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-07"]},{"parameter_id":"r_export_t","symbol":"r_t^{export}","meaning":"Export price at which the coordinator sells electricity to the retailer for time step t (feed-in-tariff export rate); a pre-announced, non-dynamic exogenous input to the MMR pricing formula.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-07"]},{"parameter_id":"r_average_t","symbol":"r_t^{average}","meaning":"Arithmetic mean of the retailer's export and retail prices, defined inside the MMR pricing model as r_t^{average} = (r_t^{retail} + r_t^{export})/2 (A25); used as the mid-market internal price in all three balance cases.","value":{"kind":"symbolic","number_value":null,"text_value":"(r_t^{retail} + r_t^{export}) / 2"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g07-ev-07"]},{"parameter_id":"e_gen_bid_nt","symbol":"e_{gen,n,t}^{bid}","meaning":"Generation-component energy bid submitted by prosumer n at time step t under MMR; an exogenous input to this pricing rule (determined by the bidding/decision model), entering the internal-price formulas only through the regional total of its absolute value, Σ_{n∈PA}|e_{gen,n,t}^{bid}|. Scoped here as pricing input, not as a decision of pricing.local.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n","t"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},{"parameter_id":"e_dem_bid_nt","symbol":"e_{dem,n,t}^{bid}","meaning":"Demand-component energy bid submitted by prosumer n at time step t under MMR; an exogenous input to this pricing rule, entering the internal-price formulas through the regional total Σ_{n∈PA} e_{dem,n,t}^{bid}. Scoped here as pricing input, not as a decision of pricing.local.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["n","t"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]}],"phi":[{"constraint_id":"v141-c-R014-C001","kind":"procedural","role":"core","statement":"Submitted generation quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","pricing.local"],"variable_refs":[],"parameter_refs":["e_gen_bid_nt"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},{"constraint_id":"v141-c-R014-C002","kind":"procedural","role":"core","statement":"Submitted demand quantities are inputs to internal-price calculation according to regional total generation relative to demand. Scope: MMR internal pricing within one energy sharing region, using separate generation and demand submissions at each time step.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","pricing.local"],"variable_refs":[],"parameter_refs":["e_dem_bid_nt"],"evidence_ids":["v141-b-g07-ev-06","v141-b-g07-ev-07"]},{"constraint_id":"v141-c-R014-C003","kind":"procedural","role":"core","statement":"The coordinator calculates internal prices using the MMR pricing model. Scope: MMR pricing within one energy sharing region.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","pricing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-ev-07"]},{"constraint_id":"v141-c-R014-C004","kind":"mathematical","role":"core","statement":"The internal buying and selling prices are equal to the arithmetic mean of the retailer's export and retail prices. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation equals total demand.","expression":"p_t^{buy} = p_t^{sell} = r_t^{average} = \\frac{r_t^{export} + r_t^{retail}}{2}, \\quad \\text{if } \\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}| = \\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["p_buy_t","p_sell_t"],"parameter_refs":["r_average_t","r_export_t","r_retail_t","e_gen_bid_nt","e_dem_bid_nt"],"evidence_ids":["v141-b-g07-ev-07"]},{"constraint_id":"v141-c-R014-C005","kind":"mathematical","role":"core","statement":"The internal selling price remains the arithmetic mean of export and retail prices; the internal buying price is adjusted to cover the regional deficit imported at the retailer's retail price. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation is less than total demand.","expression":"\\begin{cases} p_t^{buy} = \\frac{\\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}| \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid} - \\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}| \\right) \\cdot r_t^{retail}}{\\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid}} \\\\ p_t^{sell} = r_t^{average} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}| \u003c \\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["p_buy_t","p_sell_t"],"parameter_refs":["r_average_t","r_retail_t","e_gen_bid_nt","e_dem_bid_nt"],"evidence_ids":["v141-b-g07-ev-07"]},{"constraint_id":"v141-c-R014-C006","kind":"mathematical","role":"core","statement":"The internal buying price remains the arithmetic mean of export and retail prices; the internal selling price is adjusted to incorporate surplus-export income for distribution among participants providing electricity through generation or EV discharging. Scope: MMR internal prices at a given time step within one energy sharing region. Condition: Total generation exceeds total demand.","expression":"\\begin{cases} p_t^{buy} = r_t^{average} \\\\ p_t^{sell} = \\frac{\\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid} \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}| - \\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid} \\right) \\cdot r_t^{export}}{\\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}|} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{PA}} |e_{gen,n,t}^{bid}| > \\sum_{n \\in \\mathcal{PA}} e_{dem,n,t}^{bid}","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["p_buy_t","p_sell_t"],"parameter_refs":["r_average_t","r_export_t","e_gen_bid_nt","e_dem_bid_nt"],"evidence_ids":["v141-b-g07-ev-07"]}],"pi":[{"evidence_id":"v141-b-g07-ev-06","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-bidding","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A24","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:\n\ne^{bid} = e_{gen}^{bid} \\cup e_{dem}^{bid}\n= \\{ e_{gen,t}^{bid} \\mid e_{gen,t}^{bid} = (x_t^{dis*} \\eta^{dis}) - P_{PV,t}, t \\in T \\}\n\\cup \\{ e_{dem,t}^{bid} \\mid e_{dem,t}^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + P_t^{must-run} \\right), t \\in T \\}  (A24)"},{"evidence_id":"v141-b-g07-ev-07","location":{"location_id":"src-d485825b0d-p26-c2r4__v141-a-M02-pricing","page":26,"printed_page":"1018","section":"A.2.2","anchor_text":"(A24) the internal price in diﬀerent ways according to the relationship between total n is equal to ","equation_id":"A25-A27","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region. If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:\n\np_t^{buy} = p_t^{sell} = r_t^{average} = \\frac{(r_t^{export} + r_t^{retail})}{2}, \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| = \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A25)\n\nIf the generation is less than demand, the deficit generation has to be supplied by the power imported from the retailer at the retail price, and the cost of this import should be covered. Therefore, in this situation, the internal selling price keeps the same as that in Formula (A25), but the buying price is modified:\n\n\\begin{cases} p_t^{buy} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \\right) \\cdot r_t^{retail}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}} \\\\ p_t^{sell} = r_t^{average} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| \u003c \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A26)\n\nSimilarly, if the generation is higher than demand, the surplus generation needs to be sold to the retailer at the export price, and this part of income needs to be distributed among all the prosumers who provide electricity by generation or EV discharging. The internal price is calculated as follows:\n\n\\begin{cases} p_t^{buy} = r_t^{average} \\\\ p_t^{sell} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\right) \\cdot r_t^{export}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}|} \\end{cases} \\quad \\text{if } \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| > \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid}.  (A27)\n\nFormulas (A25)-(A27) compose the pricing model in the coordinator agent under mid-market rate mechanism."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-bidding","v141-a-M02-pricing"],"extras":{"decision_anchor":"pricing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g07-ev-06","quote":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:"},{"evidence_id":"v141-b-g07-ev-07","quote":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region."}],[{"evidence_id":"v141-b-g07-ev-06","quote":"The MMR mechanism requires each prosumer to provide the energy bid that contains both generation and demand at each time step separately rather than an overall net demand as that in the SDR mechanism:"},{"evidence_id":"v141-b-g07-ev-07","quote":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region."}],[{"evidence_id":"v141-b-g07-ev-07","quote":"With the energy bids of all the prosumers, the coordinator calculates the internal price in different ways according to the relationship between total generation and demand in the energy sharing region."},{"evidence_id":"v141-b-g07-ev-07","quote":"Formulas (A25)-(A27) compose the pricing model in the coordinator agent under mid-market rate mechanism."}],[{"evidence_id":"v141-b-g07-ev-07","quote":"If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:"}],[{"evidence_id":"v141-b-g07-ev-07","quote":"If the generation is less than demand, the deficit generation has to be supplied by the power imported from the retailer at the retail price, and the cost of this import should be covered. Therefore, in this situation, the internal selling price keeps the same as that in Formula (A25), but the buying price is modified:"},{"evidence_id":"v141-b-g07-ev-07","quote":"If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:"}],[{"evidence_id":"v141-b-g07-ev-07","quote":"Similarly, if the generation is higher than demand, the surplus generation needs to be sold to the retailer at the export price, and this part of income needs to be distributed among all the prosumers who provide electricity by generation or EV discharging. The internal price is calculated as follows:"},{"evidence_id":"v141-b-g07-ev-07","quote":"p_t^{buy} = r_t^{average}"},{"evidence_id":"v141-b-g07-ev-07","quote":"p_t^{sell} = \\frac{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\cdot r_t^{average} + \\left( \\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}| - \\sum_{n \\in \\mathcal{P}\\mathcal{A}} e_{dem,n,t}^{bid} \\right) \\cdot r_t^{export}}{\\sum_{n \\in \\mathcal{P}\\mathcal{A}} |e_{gen,n,t}^{bid}|}"},{"evidence_id":"v141-b-g07-ev-07","quote":"If the generation is equal to demand, the internal buying and selling price are equal, taking the average of the export and retail price:"}]],"C2_formalization":{"graph_sha256":"10871e4dee97b961cc9140c9461197553a7c15a612ab6b0880d90828b8321bd3","applicability":"formalized","reason":"The frozen MMR 'Local clearing price' rule is in substance mathematical. Verified (experimental-eligibility) B evidence v141-b-g07-ev-07 (section A.2.2, printed p.1018) supplies the exact closed-form internal-price model (A25)-(A27) for the three generation-demand balance cases, and v141-b-g07-ev-06 (A24) supplies the separate generation/demand bid components consumed by those formulas. Constraints C004, C005 and C006 are faithfully transcribed from A25, A26 and A27 respectively (formalization_origin=source). Constraints C001, C002 and C003 state only the input wiring of the bid quantities into the pricing node and the coordinator's responsibility to run the pricing model; the source does not give a standalone formula for them, so they are retained as procedural/not_formalized. No graph change is required: all symbols used by A25-A27 map onto the existing nodes/edges of this rule (bidding.demand, bidding.supply, coordination.local_operator, pricing.local), with the retailer's retail/export prices entering as exogenous parameters of pricing.local.","bindings":[{"object_id":"p_buy_t","node_ids":["pricing.local"],"edge_ids":["v141-c-R014-E001","v141-c-R014-E002","v141-c-R014-E003"],"rationale":"The internal buying price is the endogenous output of the pricing.local node. Its value is computed from the submitted demand and supply bid totals (edges E001 demand→pricing and E002 supply→pricing) and is issued by the coordinator (edge E003 coordination.local_operator→pricing.local)."},{"object_id":"p_sell_t","node_ids":["pricing.local"],"edge_ids":["v141-c-R014-E001","v141-c-R014-E002","v141-c-R014-E003"],"rationale":"The internal selling price is the endogenous output of the pricing.local node. Its value is computed from the submitted demand and supply bid totals (edges E001 and E002) and is issued by the coordinator (edge E003)."},{"object_id":"r_retail_t","node_ids":["pricing.local"],"edge_ids":[],"rationale":"Exogenous pre-announced retail price used as an input inside the pricing.local formula (A25)-(A27); the retailer counter-party is outside this rule's node/edge set, so no edge within this rule applies."},{"object_id":"r_export_t","node_ids":["pricing.local"],"edge_ids":[],"rationale":"Exogenous pre-announced export price used as an input inside the pricing.local formula (A25)-(A27); the retailer counter-party is outside this rule's node/edge set, so no edge within this rule applies."},{"object_id":"r_average_t","node_ids":["pricing.local"],"edge_ids":[],"rationale":"Defined inside the pricing.local node as the arithmetic mean of the retail and export prices, r_t^{average} = (r_t^{retail} + r_t^{export})/2 (A25); it is a derived quantity of the pricing node rather than a network-linked flow."},{"object_id":"e_gen_bid_nt","node_ids":["bidding.supply","pricing.local"],"edge_ids":["v141-c-R014-E002"],"rationale":"The generation-component bid is produced at the bidding.supply node and consumed by pricing.local through edge E002; the internal-price formulas use it through the regional total Σ_{n∈PA}|e_{gen,n,t}^{bid}|, matching the C001 input-link statement."},{"object_id":"e_dem_bid_nt","node_ids":["bidding.demand","pricing.local"],"edge_ids":["v141-c-R014-E001"],"rationale":"The demand-component bid is produced at the bidding.demand node and consumed by pricing.local through edge E001; the internal-price formulas use it through the regional total Σ_{n∈PA} e_{dem,n,t}^{bid}, matching the C002 input-link statement."},{"object_id":"v141-c-R014-C004","node_ids":["pricing.local"],"edge_ids":["v141-c-R014-E001","v141-c-R014-E002"],"rationale":"The generation-equals-demand branch (A25) is evaluated at the pricing.local node and its condition and value depend on both the demand and generation bid totals carried by edges E001 and E002."},{"object_id":"v141-c-R014-C005","node_ids":["pricing.local"],"edge_ids":["v141-c-R014-E001","v141-c-R014-E002"],"rationale":"The generation-less-than-demand branch (A26) is evaluated at the pricing.local node and its deficit term (Σ e_dem − Σ|e_gen|) depends on the demand and generation bid totals carried by edges E001 and E002."},{"object_id":"v141-c-R014-C006","node_ids":["pricing.local"],"edge_ids":["v141-c-R014-E001","v141-c-R014-E002"],"rationale":"The generation-greater-than-demand branch (A27) is evaluated at the pricing.local node and its surplus term (Σ|e_gen| − Σ e_dem) depends on the demand and generation bid totals carried by edges E001 and E002."}],"revision_requests":[]}},"quarantined_references":[]}});
